ST.xhtml:p:
RY3Trigger(CLK := g_biY3HomeEnable OR bY3HomeEnable);

IF RY3Trigger.Q THEN
    nY3HomeState := 1;
    g_boY3HomeDone := FALSE;
    bY3HomeDone := FALSE;
END_IF;

CASE nY3HomeState OF
  0:
    nY3HomeState := 0;
  1:
    g_Y3Home.Execute := TRUE;
    IF nY3HomingMode = 0 THEN
      g_Y3Home.HomingMode := 0;
      g_Y3Home.Position := dY3HomePosition;
    ELSIF nY3HomingMode = 1 THEN
      g_Y3Home.HomingMode := 5;
      g_Y3Home.Position := 0.0;
    ELSIF nY3HomingMode = 3 THEN
      g_Y3Home.HomingMode := 1;
    END_IF;

    g_Y3Home.bCalibrationCam := g_bY3AxisZero;
    IF g_Y3Home.Done THEN
      g_Y3Home.Execute := FALSE;

      IF nY3HomingMode = 3 THEN
        nY3HomeState := 0;
      ELSE
        nY3HomeState := 2;
      END_IF;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nY3HomeState := 20;
    END_IF;
    IF g_Y3Home.CommandAborted OR g_Y3Home.Error THEN
      g_Y3Home.Execute := FALSE;
      nY3HomeState := 0;
    END_IF;
  2:
    g_Y3MoveAbs.Execute := TRUE;
    g_Y3MoveAbs.Position := dY3HomeOffset;
    g_Y3MoveAbs.Velocity := dY3HomeVel;
    IF g_Y3MoveAbs.Done THEN
      g_Y3MoveAbs.Execute := FALSE;
      bY3HomeDone := TRUE;
      g_boY3HomeDone := TRUE;
      nY3HomeState := 0;
    END_IF;
     IF g_bPlcPauseBuffer THEN
      nY3HomeState := 21;
    END_IF;
  20:
    g_Y3Home.Execute := FALSE;
    g_Y3MoveStop.Execute := TRUE;
    IF g_Y3MoveStop.Done AND g_bPlcStartBuffer THEN
      g_Y3MoveStop.Execute := FALSE;
      nY3HomeState := 1;
    END_IF;
    IF g_Y3MoveStop.CommandAborted OR g_Y3MoveStop.Error THEN
      g_Y3MoveStop.Execute := FALSE;
      nY3HomeState := 0;
    END_IF;
  21:
    g_Y3Home.Execute := FALSE;
    g_Y3MoveStop.Execute := TRUE;
    IF g_Y3MoveStop.Done AND g_bPlcStartBuffer THEN
      g_Y3MoveStop.Execute := FALSE;
      nY3HomeState := 2;
    END_IF;
    IF g_Y3MoveStop.CommandAborted OR g_Y3MoveStop.Error THEN
      g_Y3MoveStop.Execute := FALSE;
      nY3HomeState := 0;
    END_IF;
END_CASE;


RY2Trigger(CLK := g_biY2HomeEnable OR bY2HomeEnable);

IF RY2Trigger.Q THEN
    nY2HomeState := 1;
    g_boY2HomeDone := FALSE;
    bY2HomeDone := FALSE;
END_IF;

CASE nY2HomeState OF
  0:
    nY2HomeState := 0;
  1:
    g_Y2Home.Execute := TRUE;
    IF nY2HomingMode = 0 THEN
      g_Y2Home.HomingMode := 0;
      g_Y2Home.Position := dY2HomePosition;
    ELSIF nY2HomingMode = 1 THEN
      g_Y2Home.HomingMode := 5;
      g_Y2Home.Position := 0.0;
    ELSIF nY2HomingMode = 3 THEN
      g_Y2Home.HomingMode := 1;
    END_IF;
    g_Y2Home.bCalibrationCam := g_bY2AxisZero;
    IF g_Y2Home.Done THEN
      g_Y2Home.Execute := FALSE;
      IF nY2HomingMode = 3 THEN
        nY2HomeState := 0;
      ELSE
        nY2HomeState := 2;
      END_IF;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nY2HomeState := 20;
    END_IF;
    IF g_Y2Home.CommandAborted OR g_Y2Home.Error THEN
      g_Y2Home.Execute := FALSE;
      nY2HomeState := 0;
    END_IF;
  2:
    g_Y2MoveAbs.Execute := TRUE;
    g_Y2MoveAbs.Position := dY2HomeOffset;
    g_Y2MoveAbs.Velocity := dY2HomeVel;
    IF g_Y2MoveAbs.Done THEN
      g_Y2MoveAbs.Execute := FALSE;
      bY2HomeDone := TRUE;
      g_boY2HomeDone := TRUE;
      nY2HomeState := 0;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nY2HomeState := 21;
    END_IF;
  20:
    g_Y2Home.Execute := FALSE;
    g_Y2MoveStop.Execute := TRUE;
    IF g_Y2MoveStop.Done AND g_bPlcStartBuffer THEN
      g_Y2MoveStop.Execute := FALSE;
      nY2HomeState := 1;
    END_IF;
    IF g_Y2MoveStop.CommandAborted OR g_Y2MoveStop.Error THEN
      g_Y2MoveStop.Execute := FALSE;
      nY2HomeState := 0;
    END_IF;
  21:
    g_Y2Home.Execute := FALSE;
    g_Y2MoveStop.Execute := TRUE;
    IF g_Y2MoveStop.Done AND g_bPlcStartBuffer THEN
      g_Y2MoveStop.Execute := FALSE;
      nY2HomeState := 2;
    END_IF;
    IF g_Y2MoveStop.CommandAborted OR g_Y2MoveStop.Error THEN
      g_Y2MoveStop.Execute := FALSE;
      nY2HomeState := 0;
    END_IF;
END_CASE;

IF bChangeHomeMode THEN
  bChangeHomeMode := FALSE;
  nChangeHomeModeState := nChangeModeAxis;
END_IF;
(*置零点功能*)
CASE nChangeHomeModeState OF
  0:
    nChangeHomeModeState := 0;
  1:
    g_Y3Home.Execute := TRUE;
    IF nY3HomingMode = 0 THEN
      g_Y3Home.HomingMode := 0;
    ELSIF nY3HomingMode = 1 THEN
      g_Y3Home.HomingMode := 5;
    ELSIF nY3HomingMode = 2 THEN
      g_Y3Home.HomingMode := 4;
    END_IF;
    IF g_Y3Home.Done THEN
      g_Y3Home.Execute := FALSE;
      nChangeHomeModeState := 0;
    END_IF;
    IF g_Y3Home.CommandAborted OR g_Y3Home.Error THEN
      g_Y3Home.Execute := FALSE;
      nChangeHomeModeState := 0;
    END_IF;
   2:
    g_Y2Home.Execute := TRUE;
    IF nY2HomingMode = 0 THEN
      g_Y2Home.HomingMode := 0;
    ELSIF nY2HomingMode = 1 THEN
      g_Y2Home.HomingMode := 5;
    ELSIF nY2HomingMode = 2 THEN
      g_Y2Home.HomingMode := 4;
    END_IF;
    IF g_Y2Home.Done THEN
      g_Y2Home.Execute := FALSE;
      nChangeHomeModeState := 0;
    END_IF;
    IF g_Y2Home.CommandAborted OR g_Y2Home.Error THEN
      g_Y2Home.Execute := FALSE;
      nChangeHomeModeState := 0;
    END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  nY2HomeState := 0;
  g_Y2MoveStop.Execute := FALSE;
  g_Y2Home.Execute := FALSE;
  g_boY2HomeDone := TRUE;
  bY2HomeDone := TRUE;

  nY3HomeState := 0;
  g_Y3MoveStop.Execute := FALSE;
  g_Y3Home.Execute := FALSE;
  g_boY3HomeDone := TRUE;
  bY3HomeDone := TRUE;

  nChangeHomeModeState := 0;
END_IF;
